(function(E){ const x = E["exam-08"] = E["exam-08"] || {units:{}}; (x.units = x.units || {})["x08-r2"] = {"id":"x08-r2","patterns":["RA-nature","GT2-career","PARA-research","PARA-cause","PARA-rules","TR-whosevoice","TR-samewords","TR-detail","TR-paraphrase","TR-limit","TR-plural"],"title":{"en":"Reading 2: Passage 2 / Section 2","tr":"Reading 2: Passage 2 / Section 2","fa":"Reading ۲: متن ۲ (Passage 2) / بخش ۲ (Section 2)"},"objective":{"en":"In this lesson you will learn to find a detail in a lettered section, complete sentences with one word from the passage, and match views to the right expert.","tr":"Bu derste harfli bir bölümde bir ayrıntıyı bulmayı, cümleleri metinden tek kelimeyle tamamlamayı ve görüşleri doğru uzmanla eşleştirmeyi öğreneceksin.","fa":"در این درس یاد می‌گیری یک جزئیات را در بخشی حرف‌دار پیدا کنی، جمله‌ها را با یک کلمه از متن کامل کنی و نظرها را با متخصص درست جور کنی."},"objectiveGT":{"en":"In this lesson you will learn to complete notes and sentences on two work-related texts, finding the paraphrase and copying one word in the text’s exact form.","tr":"Bu derste işle ilgili iki metinde notları ve cümleleri tamamlamayı öğreneceksin: eş anlamlıyı bulacak ve tek bir kelimeyi metindeki biçimiyle aynen kopyalayacaksın.","fa":"در این درس یاد می‌گیری یادداشت‌ها و جمله‌های دو متن کاری را کامل کنی: معادل را پیدا کنی و یک کلمه را دقیقاً به شکل متن کپی کنی."},"sessions":[["explain"],["drill"],["exit"]],"explain":{"title":{"en":"Reading Passage 2: solutions compared","tr":"Reading Passage 2: karşılaştırılan çözümler","fa":"Reading Passage 2: مقایسه‌ی راه‌حل‌ها"},"objective":{"en":"In this lesson you will learn to find a detail in a lettered section, complete sentences with one word from the passage, and match views to the right expert.","tr":"Bu derste harfli bir bölümde bir ayrıntıyı bulmayı, cümleleri metinden tek kelimeyle tamamlamayı ve görüşleri doğru uzmanla eşleştirmeyi öğreneceksin.","fa":"در این درس یاد می‌گیری یک جزئیات را در بخشی حرف‌دار پیدا کنی، جمله‌ها را با یک کلمه از متن کامل کنی و نظرها را با متخصص درست جور کنی."},"stats":[{"label":{"en":"Questions","tr":"Soru","fa":"سؤال"},"value":"13"},{"label":{"en":"Sections","tr":"Bölüm","fa":"بخش"},"value":"A-F"},{"label":{"en":"Experts","tr":"Uzman","fa":"متخصص"},"value":"5"}],"context":{"eyebrow":{"en":"1 The context","tr":"1 Bağlam","fa":"۱ بافت"},"head":{"en":"This exam: coastal towns and rising seas","tr":"Bu sınav: kıyı kasabaları ve yükselen deniz","fa":"این آزمون: شهرهای ساحلی و بالا آمدن آب دریا"},"intro":{"en":"Passage 2 often compares ideas and quotes several researchers. The natural world and the environment are the most frequent topic family across all Academic passages.","tr":"Passage 2 çoğu zaman fikirleri karşılaştırır ve birkaç araştırmacıdan alıntı yapar. Doğa ve çevre, tüm Academic metinler içinde en sık çıkan konu ailesidir.","fa":"Passage 2 اغلب ایده‌ها را مقایسه می‌کند و از چند پژوهشگر نقل قول می‌آورد. طبیعت و محیط زیست پرتکرارترین خانواده‌ی موضوعی در همه‌ی متن‌های Academic است."},"technique":{"en":"2 The technique","tr":"2 Teknik","fa":"۲ تکنیک"},"labels":{"asks":{"en":"What this part is about","tr":"Bu kısım ne hakkında","fa":"این بخش درباره‌ی چیست"},"fields":{"en":"Headings you will see","tr":"Göreceğin başlıklar","fa":"عنوان‌هایی که می‌بینی"},"words":{"en":"Words that carry the answers","tr":"Cevabı taşıyan kelimeler","fa":"کلمه‌هایی که جواب را می‌آورند"},"a":{"en":"On the paper","tr":"Kâğıtta","fa":"روی برگه"},"b":{"en":"What you hear or read","tr":"Duyduğun ya da okuduğun","fa":"چیزی که می‌شنوی یا می‌خوانی"},"traps":{"en":"Traps","tr":"Tuzaklar","fa":"دام‌ها"},"example":{"en":"Example","tr":"Örnek","fa":"نمونه"},"ideas":{"en":"Ideas","tr":"Fikirler","fa":"ایده‌ها"}},"cards":[{"id":"x08-r2-ctx","exam":true,"patterns":["RA-nature","PARA-research","PARA-cause"],"often":{"pattern":"RA-nature","n":37,"of":120,"label":{"en":"Comes up often in the real exam: 37 of the last 120 passages","tr":"Gerçek sınavda sık çıkar: son 120 metnin 37’sinde","fa":"در آزمون واقعی زیاد می‌آید: در ۳۷ متن از ۱۲۰ متنِ اخیر"}},"title":{"en":"How places adapt to a changing environment","tr":"Yerler değişen bir çevreye nasıl uyum sağlıyor","fa":"مکان‌ها چطور با محیطِ در حال تغییر سازگار می‌شوند"},"asks":{"en":"A passage in lettered sections compares several solutions to one environmental problem. Each solution has its supporters and critics, and five named experts give their views. You find details in sections, complete sentences and match views to people.","tr":"Harfli bölümlerden oluşan bir metin tek bir çevre sorununa birkaç çözümü karşılaştırıyor. Her çözümün destekçileri ve eleştirenleri var; adı verilen beş uzman görüşlerini söylüyor. Bölümlerde ayrıntı buluyor, cümle tamamlıyor ve görüşleri kişilerle eşleştiriyorsun.","fa":"متنی با بخش‌های حرف‌دار چند راه‌حل را برای یک مشکل محیط‌زیستی مقایسه می‌کند. هر راه‌حل موافق‌ها و منتقدهایی دارد و پنج متخصص با اسم نظرشان را می‌گویند. در بخش‌ها دنبال جزئیات می‌گردی، جمله کامل می‌کنی و نظرها را با آدم‌ها جور می‌کنی."},"fields":["The problem","Solution 1 and its side effects","Solution 2","Solution 3","The hardest option","What makes it work"],"words":[{"a":"side effects","b":"unwanted results / makes things worse elsewhere","tr":"yan etkiler","fa":"اثرهای جانبی"},{"a":"nearby","b":"neighbouring / next to it","tr":"yakındaki","fa":"نزدیک، همسایه"},{"a":"reduce","b":"absorb / weaken / lessen","tr":"azaltmak","fa":"کم کردن"},{"a":"collects","b":"traps / builds up","tr":"toplar, biriktirir","fa":"جمع می‌کند"},{"a":"cheaper to maintain","b":"costs less to look after","tr":"bakımı daha ucuz","fa":"نگه‌داری‌اش ارزان‌تر"},{"a":"dangerous places","b":"the most exposed / threatened areas","tr":"tehlikeli yerler","fa":"جاهای خطرناک"},{"a":"discourage","b":"make people think twice","tr":"caydırmak","fa":"منصرف کردن"},{"a":"refuse to move","b":"won’t leave / stay on","tr":"taşınmayı reddetmek","fa":"از رفتن سر باز زدن"},{"a":"abandon","b":"leave / give up","tr":"terk etmek","fa":"رها کردن"},{"a":"review regularly","b":"look at again every few years","tr":"düzenli olarak gözden geçirmek","fa":"مرتب بازبینی کردن"},{"a":"argues","b":"believes / says / points out","tr":"savunuyor","fa":"استدلال می‌کند"},{"a":"critics reply","b":"others disagree / opponents say","tr":"eleştirenler karşılık veriyor","fa":"منتقدها جواب می‌دهند"}],"traps":[{"en":"A name appears in two sections. Read both before you match a view: Oduya speaks about walls in one place and about flexibility in another.","tr":"Bir isim iki bölümde geçer. Bir görüşü eşleştirmeden önce ikisini de oku: Oduya bir yerde duvarlardan, başka bir yerde esneklikten söz ediyor.","fa":"یک اسم در دو بخش می‌آید. قبل از جور کردن نظر، هر دو را بخوان: اودویا یک‌جا درباره‌ی دیوار حرف می‌زند و جای دیگر درباره‌ی انعطاف."},{"en":"\"Critics reply...\" is not the view of the expert named just before. Check whose voice each sentence is.","tr":"\"Critics reply...\" hemen önce adı geçen uzmanın görüşü değildir. Her cümlenin kimin sesi olduğuna bak.","fa":"«Critics reply...» نظر متخصصی نیست که درست قبلش اسمش آمده. ببین هر جمله صدای چه کسی است."},{"en":"Matching information looks for one detail, such as an example or a reason, not for the main topic of the section.","tr":"Bilgi eşleştirme bölümün ana konusunu değil, bir örnek ya da bir neden gibi tek bir ayrıntıyı arar.","fa":"جور کردن اطلاعات دنبال یک جزئیات است، مثل یک مثال یا یک دلیل، نه موضوع اصلی بخش."}],"example":{"text":"\"The economist Lena Ruiz believes tolls reduce traffic. Critics reply that tolls hurt poorer drivers most.\"","item":"Who says tolls are unfair to people with less money? A Lena Ruiz  B not Ruiz: the critics","answer":"B","why":{"en":"\"Critics reply\" introduces a different voice. Ruiz only says tolls reduce traffic.","tr":"\"Critics reply\" farklı bir ses getiriyor. Ruiz yalnızca geçiş ücretinin trafiği azalttığını söylüyor.","fa":"«Critics reply» صدای دیگری را می‌آورد. روییز فقط می‌گوید عوارض ترافیک را کم می‌کند."}}},{"id":"RA-nature-report","ctx":["RA-nature"],"title":{"en":"Reports on ecosystems and the environment","tr":"Ekosistemler ve çevre üzerine raporlar","fa":"گزارش درباره‌ی زیست‌بوم‌ها و محیط زیست"},"asks":{"en":"A report in lettered paragraphs about an ecosystem or an environmental problem: what it is, why it matters, what threatens it and what is being done. Headings name each paragraph’s main idea; matching information asks where one detail is.","tr":"Bir ekosistem ya da çevre sorunu hakkında harfli paragraflardan oluşan bir rapor: ne olduğu, neden önemli olduğu, onu neyin tehdit ettiği ve neler yapıldığı. Başlıklar her paragrafın ana fikrini adlandırır; bilgi eşleştirme tek bir ayrıntının nerede olduğunu sorar.","fa":"گزارشی با پاراگراف‌های حرف‌دار درباره‌ی یک زیست‌بوم یا یک مشکل محیط‌زیستی: چیست، چرا مهم است، چه چیزی تهدیدش می‌کند و چه کاری انجام می‌شود. عنوان‌ها ایده‌ی اصلی هر پاراگراف‌اند؛ جورکردن اطلاعات می‌پرسد یک نکته‌ی جزئی کجاست."},"fields":["The economic value of the forest","An unexpected benefit","Causes of decline","Early attempts at protection","A way of measuring change","Which paragraph mentions a comparison with another region?"],"words":[{"a":"a threat to","b":"puts at risk / endangers","tr":"... için tehdit","fa":"تهدیدی برای"},{"a":"causes","b":"the reasons / what led to","tr":"nedenler","fa":"علت‌ها"},{"a":"an unexpected benefit","b":"a surprising advantage","tr":"beklenmedik bir fayda","fa":"فایده‌ای غیرمنتظره"},{"a":"economic value","b":"worth money / income from","tr":"ekonomik değer","fa":"ارزش اقتصادی"},{"a":"early attempts","b":"the first efforts / initially tried","tr":"ilk girişimler","fa":"تلاش‌های اولیه"},{"a":"a new approach","b":"a different method / instead, now","tr":"yeni bir yaklaşım","fa":"رویکردی تازه"},{"a":"measuring","b":"monitoring / recording","tr":"ölçme","fa":"اندازه‌گیری"},{"a":"restore","b":"bring back / replant","tr":"eski haline getirmek","fa":"احیا کردن"},{"a":"long-term","b":"over decades / in the future","tr":"uzun vadeli","fa":"بلندمدت"},{"a":"local communities","b":"people living nearby","tr":"yerel halk","fa":"جوامع محلی"},{"a":"a comparison","b":"unlike / whereas in","tr":"bir karşılaştırma","fa":"یک مقایسه"},{"a":"consequences","b":"effects / results","tr":"sonuçlar","fa":"پیامدها"}],"traps":[{"en":"The detail trap: one heading matches a single detail of the paragraph, not its main idea.","tr":"Ayrıntı tuzağı: bir başlık paragrafın ana fikrine değil, tek bir ayrıntısına uyar.","fa":"دام جزئیات: یک عنوان با یک نکته‌ی جزئیِ پاراگراف جور است، نه با ایده‌ی اصلی‌اش."},{"en":"Matching information: the detail may sit in a paragraph whose main idea is something else.","tr":"Bilgi eşleştirme: ayrıntı, ana fikri başka bir şey olan bir paragrafta olabilir.","fa":"جورکردن اطلاعات: جزئیات ممکن است در پاراگرافی باشد که ایده‌ی اصلی‌اش چیز دیگری است."}],"example":{"text":"D  Restoring peat bogs was once thought to be simple: block the drains and wait for the water to return. Yet in many early projects the peat stayed dry for years, because the bogs had sunk below the level of the land around them.","item":"Choose the heading for paragraph D:  i  Why early restoration often failed   ii  The value of peat for farming   iii  How drains are built","answer":"i","why":{"en":"\"Once thought to be simple... yet... stayed dry\" = early attempts that failed. Drains are only a detail.","tr":"\"Bir zamanlar basit sanılıyordu... ama... kuru kaldı\" = başarısız ilk girişimler. Kanallar yalnızca bir ayrıntı.","fa":"«زمانی ساده تصور می‌شد... ولی... خشک ماند» = تلاش‌های اولیه‌ی ناموفق. زهکش‌ها فقط یک نکته‌ی جزئی‌اند."}},"track":"academic","general":true,"patterns":["RA-nature"],"often":{"pattern":"RA-nature","n":37,"of":120,"label":{"en":"Comes up often in the real exam: 37 of the last 120 passages","tr":"Gerçek sınavda sık çıkar: son 120 metnin 37’sinde","fa":"در آزمون واقعی زیاد می‌آید: در ۳۷ متن از ۱۲۰ متنِ اخیر"}}}]},"points":[{"eyebrow":{"en":"In the exam","tr":"Sınavda","fa":"در آزمون"},"head":{"en":"Sections, sentences, people","tr":"Bölümler, cümleler, kişiler","fa":"بخش‌ها، جمله‌ها، آدم‌ها"},"body":{"en":"Questions 14-17: which section, A-F, contains each piece of information (a letter can be used twice). Questions 18-22: complete sentences with ONE WORD ONLY. Questions 23-26: match statements to five people, A-E.","tr":"Soru 14-17: her bilgi hangi bölümde, A-F (bir harf iki kez kullanılabilir). Soru 18-22: cümleleri YALNIZCA BİR KELİMEYLE tamamla. Soru 23-26: ifadeleri beş kişiyle (A-E) eşleştir.","fa":"سؤال‌های ۱۴ تا ۱۷: هر اطلاعات در کدام بخش (A تا F) است (یک حرف را می‌شود دو بار به کار برد). سؤال‌های ۱۸ تا ۲۲: جمله‌ها را فقط با یک کلمه کامل کن. سؤال‌های ۲۳ تا ۲۶: جمله‌ها را با پنج نفر (A تا E) جور کن."}},{"eyebrow":{"en":"The method","tr":"Yöntem","fa":"روش"},"head":{"en":"An order that saves time","tr":"Zaman kazandıran bir sıra","fa":"ترتیبی که وقت را نگه می‌دارد"},"steps":[{"en":"Do the sentences first: they follow the passage, so they show you where everything is.","tr":"Önce cümleleri yap: metnin sırasını izlerler, böylece her şeyin nerede olduğunu gösterirler.","fa":"اول جمله‌ها را حل کن: به ترتیب متن‌اند، پس نشان می‌دهند همه‌چیز کجاست."},{"en":"Circle each expert’s name every time it appears, and read the sentences around it.","tr":"Her uzmanın adını geçtiği her yerde daire içine al ve etrafındaki cümleleri oku.","fa":"اسم هر متخصص را هر جا آمد دور کن و جمله‌های اطرافش را بخوان."},{"en":"For \"which section\", look for the kind of detail named: an example, a reason, a comparison.","tr":"\"Hangi bölüm\" için istenen ayrıntı türünü ara: bir örnek, bir neden, bir karşılaştırma.","fa":"برای «کدام بخش» دنبال نوع جزئیاتی بگرد که خواسته شده: مثال، دلیل، مقایسه."},{"en":"Copy gap words exactly; check the grammar of the sentence fits.","tr":"Boşluk kelimelerini aynen kopyala; cümlenin dilbilgisine uyduğunu kontrol et.","fa":"کلمه‌ی جای خالی را دقیق کپی کن؛ مطمئن شو با دستور جمله جور است."}]},{"eyebrow":{"en":"The trap","tr":"Tuzak","fa":"دام"},"head":{"en":"Whose voice is it?","tr":"Bu kimin sesi?","fa":"این صدای کیست؟"},"table":{"headers":{"en":["In the passage","Whose view?"],"tr":["Metinde","Kimin görüşü?"],"fa":["در متن","نظرِ چه کسی؟"]},"rows":[["\"...,\" says Brooks.","Brooks"],["Critics reply that...","not the expert just named"],["Oduya agrees that...","Oduya (a second mention)"],["There is no single model.","the writer"]]}}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"One view, step by step","tr":"Bir görüş, adım adım","fa":"یک نظر، قدم به قدم"},"instruction":"Match each statement with the correct person, A-C.","text":"\"Dr Amal Zayed thinks parks cool cities. Professor Ian Hart doubts this. ‘Trees help,’ Hart admits, ‘but only where they are planted densely.’\"","item":"Statement: Trees only make a difference if there are many of them close together.","answer":"Ian Hart","walk":[{"en":"Find the idea: \"densely\" = many, close together.","tr":"Fikri bul: \"densely\" = çok sayıda, birbirine yakın.","fa":"ایده را پیدا کن: «densely» یعنی زیاد و نزدیک به هم."},{"en":"Check the voice: the quote belongs to Hart, not Zayed.","tr":"Sesi kontrol et: alıntı Zayed’e değil, Hart’a ait.","fa":"صدا را چک کن: نقل قول مال هارت است، نه زاید."},{"en":"\"But only where\" matches \"only if\": Hart.","tr":"\"But only where\", \"only if\" ile eşleşiyor: Hart.","fa":"«but only where» با «only if» جور است: هارت."}]},"quick":{"prompt":"\"The planner Rosa Lind supports cycle lanes. Shop owners argue that they reduce parking.\" Who thinks cycle lanes cause a problem?","options":["the shop owners","Rosa Lind","both"],"correct":0,"why":{"en":"Lind supports them; the problem (less parking) is the shop owners’ view.","tr":"Lind onları destekliyor; sorun (daha az otopark) dükkân sahiplerinin görüşü.","fa":"لیند از آن‌ها حمایت می‌کند؛ مشکل (پارکینگ کمتر) نظر مغازه‌دارهاست."}},"remember":{"en":"Find the detail, not the topic; and before matching a view, check whose voice it is.","tr":"Konuyu değil ayrıntıyı bul; bir görüşü eşleştirmeden önce kimin sesi olduğuna bak.","fa":"جزئیات را پیدا کن، نه موضوع را؛ و قبل از جور کردن نظر، ببین صدای کیست."},"type":"explain","id":"c-x08-r2-e","course":"ielts-exams","exam":"exam-08","unit":"x08-r2"},"drill":{"type":"drill","skill":"reading","part":"Academic Reading Passage 2","title":{"en":"Living with the tide","tr":"Gelgitle yaşamak","fa":"زندگی با جزر و مد"},"timed":20,"ctx":["RA-nature"],"intro":"You should spend about 20 minutes on Questions 14-26, which are based on Reading Passage 2 below.","passage":"Living with the tide\n\nA  For centuries, coastal towns responded to the sea in one way: they built a wall. As sea levels rise and winter storms grow stronger, that answer is being questioned. Engineers can still build higher barriers, but the cost of protecting every stretch of coast in this way would be enormous, and in many places it would simply move the problem elsewhere. Instead, a growing number of towns are trying to adapt, combining several approaches that suit their own geography, economy and people. There is no single model, and researchers disagree about which methods deserve the most money.\n\nB  Hard defences still have a place. A concrete sea wall can protect a harbour or a town centre for decades, and for some historic ports there is no realistic alternative. But walls have side effects. By reflecting waves rather than absorbing them, they can scour away the beach in front and speed up erosion on neighbouring stretches of coast, where the waves arrive with more force. The engineer Samuel Oduya points to another, less visible, problem. \"A wall makes people feel completely safe,\" he says, \"and that feeling encourages more building right behind it. When a wall is eventually overtopped, there is far more to lose than there was before it was built.\"\n\nC  The alternative that has attracted most attention uses nature itself. Salt marshes, sand dunes and shellfish reefs all reduce the energy of waves before they reach the shore. According to the ecologist Aiyana Brooks, the greatest advantage of a marsh is that it is not fixed. \"As the sea rises, a healthy marsh traps sediment and grows upwards with it,\" she explains. \"A wall can only get lower relative to the water.\" She also argues that natural defences are cheaper to look after over time, since they repair themselves after most storms. In the Netherlands, engineers have gone a step further, placing a vast artificial peninsula of sand off the coast and leaving currents to spread it gradually along the beaches, which has saved the cost of repeatedly topping them up by ship.\n\nD  A third approach accepts that water will sometimes come in and makes buildings ready for it. In several low-lying towns, new homes are raised on stilts so that floodwater can pass underneath; elsewhere, ground floors are built with tiled walls, raised electrical sockets and drains that let water out quickly. A few towns have experimented with floating houses, which rise with the water on fixed posts, although these remain expensive and are mostly found in calm harbours and lakes. The economist Tobias Renner believes that money can do as much as design. \"If insurance reflects the real level of risk,\" he says, \"people think twice before buying a house in the most exposed streets, and builders think twice about putting houses there.\" Critics reply that higher premiums hit poorer households hardest, and that a town cannot adapt if its residents cannot afford to stay.\n\nE  The most difficult option, politically, is to leave. In what planners call managed retreat, homes and roads in the most threatened areas are gradually abandoned, sometimes with public money used to buy properties from their owners. In theory this is the most permanent solution; in practice it is rarely popular. Even where land has been bought, the old roads, pipes and sea defences must often be maintained for years, because some residents choose to remain until the end. The sociologist Hélène Marchetti has interviewed residents in villages facing this choice. \"Planners tend to count houses and roads,\" she says, \"but for the people living there, a place holds family history, friendships and a sense of who they are. That loss is almost never included in the calculations, and it explains why so many people refuse to move even when they are offered a fair price.\"\n\nF  What, then, makes adaptation succeed? The urban planner Marta Kowalczyk, who has advised several coastal councils, argues that the method matters less than the process. Towns that involve residents from the start, explain the risks honestly and combine several approaches tend to make better decisions than those that simply follow national guidelines. Local knowledge matters too: fishermen and long-term residents often know which streets flood first and where the beach has been shrinking for years. She also warns against treating any plan as final. \"The science is changing, the sea is changing and so are the towns,\" she says. \"A coastal plan should be looked at again every five years at least, or it will be out of date before it is finished.\" Oduya agrees that flexibility is essential, though he adds that a few places, such as major ports, will always need walls of some kind.","groups":[{"instruction":"Questions 14-17. Reading Passage 2 has six sections, A-F. Which section contains the following information? Write the correct letter, A-F, in boxes 14-17 on your answer sheet. NB You may use any letter more than once.","qtype":"match-info","bank":["A","B","C","D","E","F"],"questions":[{"n":14,"kind":"match","prompt":"a reference to a financial way of discouraging building in dangerous places","correct":3,"evidence":"If insurance reflects the real level of risk","why":{"en":"D: Renner says insurance that reflects the risk makes people and builders \"think twice\".","tr":"D: Renner, riski yansıtan sigortanın insanları ve inşaatçıları \"iki kez düşündürdüğünü\" söylüyor.","fa":"D: رنر می‌گوید بیمه‌ای که خطر واقعی را نشان بدهد، مردم و سازنده‌ها را وادار می‌کند «دو بار فکر کنند»."},"trap":["TR-detail","TR-paraphrase"]},{"n":15,"kind":"match","prompt":"a description of how one form of protection can make conditions worse for nearby areas","correct":1,"evidence":"speed up erosion on neighbouring stretches of coast","why":{"en":"B: walls \"speed up erosion on neighbouring stretches of coast\".","tr":"B: duvarlar \"komşu kıyı şeritlerinde aşınmayı hızlandırır\".","fa":"B: دیوارها «فرسایش را در بخش‌های ساحلیِ همسایه سریع‌تر می‌کنند»."},"trap":["TR-paraphrase"]},{"n":16,"kind":"match","prompt":"an explanation of why people often refuse to move away","correct":4,"evidence":"it explains why so many people refuse to move","why":{"en":"E: a place holds \"family history, friendships and a sense of who they are\".","tr":"E: bir yer \"aile tarihi, dostluklar ve kim olduklarına dair bir duygu\" taşır.","fa":"E: یک مکان «تاریخ خانوادگی، دوستی‌ها و حسِ اینکه چه کسی هستند» را در خود دارد."},"trap":["TR-detail"]},{"n":17,"kind":"match","prompt":"an example of moving water being used to spread material along a coast","correct":2,"evidence":"leaving currents to spread it gradually along the beaches","why":{"en":"C: the sand peninsula in the Netherlands, which currents spread along the beaches.","tr":"C: Hollanda’daki kum yarımadası; akıntılar kumu kumsallar boyunca yayıyor.","fa":"C: شبه‌جزیره‌ی شنی در هلند که جریان‌های آب شنش را در طول ساحل پخش می‌کنند."},"trap":["TR-paraphrase"]}]},{"instruction":"Questions 18-22. Complete the sentences below. Choose ONE WORD ONLY from the passage for each answer. Write your answers in boxes 18-22 on your answer sheet.","qtype":"sentence","questions":[{"n":18,"kind":"gap","prompt":"According to Oduya, a sea wall can encourage more ___ directly behind it.","accept":["building"],"limit":1,"evidence":"encourages more building right behind it","why":{"en":"\"That feeling encourages more building right behind it\": right behind = directly behind.","tr":"\"Bu his, hemen arkasında daha fazla yapılaşmayı teşvik ediyor\": right behind = directly behind.","fa":"«این حس باعث ساخت‌وساز بیشتر درست پشت آن می‌شود»: right behind یعنی directly behind."},"trap":["TR-paraphrase"]},{"n":19,"kind":"gap","prompt":"Salt marshes, dunes and reefs reduce the ___ of waves.","accept":["energy"],"limit":1,"evidence":"reduce the energy of waves before they reach the shore","why":{"en":"\"All reduce the energy of waves before they reach the shore.\"","tr":"\"Hepsi dalgaların enerjisini kıyıya ulaşmadan azaltır.\"","fa":"«همه‌شان انرژی موج‌ها را پیش از رسیدن به ساحل کم می‌کنند»."},"trap":["TR-paraphrase"]},{"n":20,"kind":"gap","prompt":"Brooks says a marsh can rise with the sea because it collects ___.","accept":["sediment"],"limit":1,"evidence":"a healthy marsh traps sediment and grows upwards with it","why":{"en":"\"Traps sediment\" = collects it.","tr":"\"Tortu tutar\" = toplar.","fa":"«رسوب را به دام می‌اندازد» یعنی جمعش می‌کند."},"trap":["TR-paraphrase","TR-whosevoice"]},{"n":21,"kind":"gap","prompt":"Some new homes are built on ___ to let floodwater flow beneath them.","accept":["stilts"],"limit":1,"evidence":"new homes are raised on stilts","why":{"en":"\"Raised on stilts so that floodwater can pass underneath.\" Keep the plural.","tr":"\"Su baskını altından geçsin diye kazıklar üzerine yükseltilmiş.\" Çoğulu koru.","fa":"«روی پایه‌های بلند ساخته می‌شوند تا آب سیل از زیرشان رد شود». جمع را نگه دار."},"trap":["TR-plural"]},{"n":22,"kind":"gap","prompt":"Gradually abandoning threatened areas is known as managed ___.","accept":["retreat"],"limit":1,"evidence":"what planners call managed retreat","why":{"en":"\"What planners call managed retreat\": known as = called.","tr":"\"Planlamacıların managed retreat dediği şey\": known as = called.","fa":"«چیزی که برنامه‌ریزها managed retreat می‌نامند»: known as یعنی called."},"trap":["TR-limit"]}]},{"instruction":"Questions 23-26. Look at the following statements (Questions 23-26) and the list of people below. Match each statement with the correct person, A, B, C, D or E. Write the correct letter, A-E, in boxes 23-26 on your answer sheet. NB You may use any letter more than once.","qtype":"match-features","bank":["A Marta Kowalczyk","B Tobias Renner","C Aiyana Brooks","D Samuel Oduya","E Hélène Marchetti"],"questions":[{"n":23,"kind":"match","prompt":"Plans for the coast need to be reviewed regularly.","correct":0,"evidence":"A coastal plan should be looked at again every five years at least","why":{"en":"Kowalczyk: a plan should be \"looked at again every five years at least\".","tr":"Kowalczyk: bir plan \"en az beş yılda bir yeniden gözden geçirilmeli\".","fa":"کوالچیک: یک طرح باید «دست‌کم هر پنج سال دوباره بررسی شود»."},"trap":["TR-whosevoice","TR-paraphrase"]},{"n":24,"kind":"match","prompt":"Natural defences cost less to maintain than built ones.","correct":2,"evidence":"natural defences are cheaper to look after over time","why":{"en":"Brooks: \"cheaper to look after over time\". Oduya talks about walls, but not about cost.","tr":"Brooks: \"zamanla bakımı daha ucuz\". Oduya duvarlardan söz ediyor ama maliyetten değil.","fa":"بروکس: «نگه‌داری‌شان در طول زمان ارزان‌تر است». اودویا از دیوار حرف می‌زند، نه از هزینه."},"trap":["TR-whosevoice"]},{"n":25,"kind":"match","prompt":"The price of insurance can affect where people decide to live.","correct":1,"evidence":"people think twice before buying a house in the most exposed streets","why":{"en":"Renner: insurance that reflects the risk makes people think twice before buying in exposed streets.","tr":"Renner: riski yansıtan sigorta, insanların riskli sokaklarda ev almadan önce iki kez düşünmesini sağlar.","fa":"رنر: بیمه‌ای که خطر را نشان بدهد باعث می‌شود مردم پیش از خرید خانه در خیابان‌های پرخطر دو بار فکر کنند."},"trap":["TR-whosevoice","TR-paraphrase"]},{"n":26,"kind":"match","prompt":"Planners rarely consider what a place means to the people who live there.","correct":4,"evidence":"That loss is almost never included in the calculations","why":{"en":"Marchetti: planners \"count houses and roads\", and the loss of history and identity is \"almost never included\".","tr":"Marchetti: planlamacılar \"evleri ve yolları sayar\"; tarihin ve kimliğin kaybı \"neredeyse hiç hesaba katılmaz\".","fa":"مارکتی: برنامه‌ریزها «خانه‌ها و جاده‌ها را می‌شمارند» و از دست رفتن تاریخ و هویت «تقریباً هیچ‌وقت حساب نمی‌شود»."},"trap":["TR-whosevoice","TR-paraphrase"]}]}],"id":"c-x08-r2-d","course":"ielts-exams","exam":"exam-08","unit":"x08-r2"},"exit":{"type":"exit","items":[{"tests":"word","point":1,"prompt":"\"The walls speed up erosion on neighbouring stretches of coast.\" Erosion is...","options":["the building of new beaches","the rise of the sea level","the wearing away of land by water or wind"],"correct":2,"why":{"en":"Erosion = land slowly worn away, here by waves.","tr":"Erosion = toprağın, burada dalgalarla, yavaş yavaş aşınması.","fa":"erosion یعنی فرسایش، ساییده شدنِ آهسته‌ی زمین، این‌جا با موج."}},{"tests":"paraphrase","point":3,"prompt":"A statement says \"should be reviewed regularly\". Which words in a passage match it?","options":["was reviewed once","should be looked at again every few years","has been criticised"],"correct":1,"why":{"en":"\"Looked at again every few years\" = reviewed regularly.","tr":"\"Birkaç yılda bir yeniden bakılmalı\" = düzenli olarak gözden geçirilmeli.","fa":"«هر چند سال یک بار دوباره بررسی شود» یعنی مرتب بازبینی شود."}},{"tests":"method","point":2,"prompt":"Which group of questions should you usually do first in this passage?","options":["the sentences, because they follow the passage order","the people, because the names are easy to find","the sections, because they are first on the page"],"correct":0,"why":{"en":"Sentence completion follows the passage, so it shows you where things are before the harder matching tasks.","tr":"Cümle tamamlama metnin sırasını izler; zor eşleştirmelerden önce her şeyin yerini gösterir.","fa":"کامل کردن جمله به ترتیب متن است و قبل از جورکردن‌های سخت‌تر نشان می‌دهد هر چیز کجاست."}},{"tests":"trap","point":3,"prompt":"\"Professor Kim supports the new law. Critics reply that it will cost jobs.\" Statement: \"The new law could lead to job losses.\" Who says this?","options":["Professor Kim","both","the critics"],"correct":2,"why":{"en":"\"Critics reply\" is a different voice from Kim.","tr":"\"Critics reply\", Kim’den farklı bir ses.","fa":"«Critics reply» صدایی غیر از کیم است."}}],"id":"c-x08-r2-x","course":"ielts-exams","exam":"exam-08","unit":"x08-r2"},"gt":{"explain":{"title":{"en":"GT Reading Section 2: work texts","tr":"GT Reading Section 2: iş metinleri","fa":"GT Reading Section 2: متن‌های کاری"},"objective":{"en":"In this lesson you will learn to complete notes and sentences on two work-related texts, finding the paraphrase and copying one word in the text’s exact form.","tr":"Bu derste işle ilgili iki metinde notları ve cümleleri tamamlamayı öğreneceksin: eş anlamlıyı bulacak ve tek bir kelimeyi metindeki biçimiyle aynen kopyalayacaksın.","fa":"در این درس یاد می‌گیری یادداشت‌ها و جمله‌های دو متن کاری را کامل کنی: معادل را پیدا کنی و یک کلمه را دقیقاً به شکل متن کپی کنی."},"stats":[{"label":{"en":"Questions","tr":"Soru","fa":"سؤال"},"value":"13"},{"label":{"en":"Texts","tr":"Metin","fa":"متن"},"value":"2"},{"label":{"en":"Word limit","tr":"Kelime sınırı","fa":"سقف کلمه"},"value":{"en":"1 word","tr":"1 kelime","fa":"۱ کلمه"}}],"context":{"eyebrow":{"en":"1 The context","tr":"1 Bağlam","fa":"۱ بافت"},"head":{"en":"This exam: translation work and cover letters","tr":"Bu sınav: çeviri işi ve ön yazılar","fa":"این آزمون: کار ترجمه و نامه‌ی همراه رزومه"},"intro":{"en":"GT Section 2 is always about work. Career guides and job-application advice are the most frequent kind of text in this section.","tr":"GT Section 2 her zaman işle ilgilidir. Kariyer rehberleri ve iş başvurusu tavsiyeleri bu bölümde en sık çıkan metin türüdür.","fa":"GT Section 2 همیشه درباره‌ی کار است. راهنمای شغلی و توصیه برای درخواست کار پرتکرارترین نوع متن در این بخش‌اند."},"technique":{"en":"2 The technique","tr":"2 Teknik","fa":"۲ تکنیک"},"labels":{"asks":{"en":"What this part is about","tr":"Bu kısım ne hakkında","fa":"این بخش درباره‌ی چیست"},"fields":{"en":"Headings you will see","tr":"Göreceğin başlıklar","fa":"عنوان‌هایی که می‌بینی"},"words":{"en":"Words that carry the answers","tr":"Cevabı taşıyan kelimeler","fa":"کلمه‌هایی که جواب را می‌آورند"},"a":{"en":"On the paper","tr":"Kâğıtta","fa":"روی برگه"},"b":{"en":"What you hear or read","tr":"Duyduğun ya da okuduğun","fa":"چیزی که می‌شنوی یا می‌خوانی"},"traps":{"en":"Traps","tr":"Tuzaklar","fa":"دام‌ها"},"example":{"en":"Example","tr":"Örnek","fa":"نمونه"},"ideas":{"en":"Ideas","tr":"Fikirler","fa":"ایده‌ها"}},"cards":[{"id":"x08-r2gt-ctx","exam":true,"patterns":["GT2-career","PARA-rules"],"often":{"pattern":"GT2-career","n":18,"of":55,"label":{"en":"Comes up often in the real exam: 18 of the last 55 texts","tr":"Gerçek sınavda sık çıkar: son 55 metnin 18’inde","fa":"در آزمون واقعی زیاد می‌آید: در ۱۸ متن از ۵۵ متنِ اخیر"}},"title":{"en":"A career article and a job-seeker’s guide","tr":"Bir kariyer yazısı ve iş arayanlar için bir rehber","fa":"یک مقاله‌ی شغلی و راهنمای کارجوها"},"asks":{"en":"Two work texts: an article about one career (qualifications, finding clients, pay, problems, the future) and a guide with advice for job applications. You complete notes on the first and sentences on the second.","tr":"İş dünyasından iki metin: bir meslek hakkında bir yazı (nitelikler, müşteri bulmak, ücret, sorunlar, gelecek) ve iş başvuruları için tavsiyeler içeren bir rehber. Birincisinde notları, ikincisinde cümleleri tamamlıyorsun.","fa":"دو متن کاری: مقاله‌ای درباره‌ی یک شغل (مدرک، پیدا کردن مشتری، درآمد، مشکلات، آینده) و راهنمایی با توصیه‌هایی برای درخواست کار. در اولی یادداشت‌ها و در دومی جمله‌ها را کامل می‌کنی."},"fields":["Qualifications","Finding work","Pay","Problems","The future","Length and layout","Who to address","What to include"],"words":[{"a":"expected","b":"required / increasingly asked for","tr":"beklenen","fa":"مورد انتظار"},{"a":"charge more","b":"earn higher rates","tr":"daha fazla ücret almak","fa":"پول بیشتری گرفتن"},{"a":"a steady flow of work","b":"regular jobs","tr":"düzenli iş akışı","fa":"جریان منظم کار"},{"a":"listed in","b":"appear in / included in","tr":"... içinde listelenmiş","fa":"در ... فهرست شده"},{"a":"isolated","b":"lonely / working alone","tr":"yalnız, yalıtılmış","fa":"تنها، منزوی"},{"a":"a post","b":"a position / a vacancy / a job","tr":"pozisyon","fa":"سِمَت، جای خالی شغلی"},{"a":"recruiters","b":"the people who choose staff","tr":"işe alımcılar","fa":"مسئولان استخدام"},{"a":"requirements","b":"what the job asks for","tr":"gereklilikler","fa":"شرایط لازم"},{"a":"genuinely interested","b":"really keen / not just any job","tr":"gerçekten ilgili","fa":"واقعاً علاقه‌مند"},{"a":"careless","b":"not checked / full of mistakes","tr":"özensiz","fa":"بی‌دقت"}],"traps":[{"en":"Notes paraphrase the text: \"clients usually ask for\" for \"most customers now request\". Find the meaning, then copy the word in the text’s form.","tr":"Notlar metni başka kelimelerle söyler: \"most customers now request\" yerine \"clients usually ask for\". Anlamı bul, sonra kelimeyi metindeki biçimiyle kopyala.","fa":"یادداشت‌ها متن را با کلمه‌های دیگر می‌گویند: «clients usually ask for» به‌جای «most customers now request». معنی را پیدا کن و بعد کلمه را به شکل متن کپی کن."},{"en":"ONE WORD ONLY: if the text says \"a weekly meeting\" and \"weekly\" is printed, the answer is meeting, not \"weekly meeting\".","tr":"ONE WORD ONLY: metin \"a weekly meeting\" diyorsa ve \"weekly\" zaten yazılıysa cevap meeting’dir, \"weekly meeting\" değil.","fa":"ONE WORD ONLY: اگر متن می‌گوید «a weekly meeting» و «weekly» از قبل نوشته شده، جواب meeting است، نه «weekly meeting»."}],"example":{"text":"\"For the first three months, new staff are paid every week. After that, pay goes into your bank account once a month.\"","item":"Sentence: At first, new staff receive their pay every ___.","answer":"week","why":{"en":"\"At first\" = the first three months. Copy the word from the text: week. \"Month\" is the later rule.","tr":"\"At first\" = ilk üç ay. Kelimeyi metinden kopyala: week. \"Month\" sonraki kural.","fa":"«at first» یعنی سه ماه اول. کلمه را از متن کپی کن: week. «month» قانونِ بعدی است."}}},{"id":"GT2-career","ctx":["GT2-career"],"title":{"en":"Job and career guides","tr":"İş ve kariyer rehberleri","fa":"راهنمای کار و مسیر شغلی"},"asks":{"en":"Guides for job seekers and employees: CVs, interviews, promotion, resigning, freelance work, apprenticeships. Sentence and note completion test the advice.","tr":"İş arayanlar ve çalışanlar için rehberler: özgeçmiş, mülakat, terfi, istifa, serbest çalışma, çıraklık. Cümle ve not tamamlama tavsiyeleri sınar.","fa":"راهنما برای کارجوها و کارمندها: رزومه، مصاحبه، ترفیع، استعفا، کار آزاد، کارآموزی حرفه‌ای. کامل کردن جمله و یادداشت توصیه‌ها را می‌سنجد."},"fields":["Keep your CV to ___ pages.","Research the company before the ___.","Give your employer written ___ when you resign.","Freelancers must keep records for ___."],"words":[{"a":"CV","b":"career summary / résumé","tr":"özgeçmiş","fa":"رزومه"},{"a":"applicant","b":"candidate / person applying","tr":"başvuran","fa":"متقاضی"},{"a":"vacancy","b":"an open job","tr":"açık pozisyon","fa":"موقعیت شغلی خالی"},{"a":"interview","b":"meeting with the employer","tr":"mülakat","fa":"مصاحبه"},{"a":"resign","b":"leave your job / hand in your notice","tr":"istifa etmek","fa":"استعفا دادن"},{"a":"notice period","b":"time between resigning and leaving","tr":"ihbar süresi","fa":"مدت اطلاع قبلی"},{"a":"promotion","b":"moving up to a higher job","tr":"terfi","fa":"ترفیع"},{"a":"freelance","b":"self-employed / working for yourself","tr":"serbest","fa":"آزادکار"},{"a":"apprenticeship","b":"training while you work","tr":"çıraklık","fa":"کارآموزی حرفه‌ای"},{"a":"references","b":"people who will recommend you","tr":"referanslar","fa":"معرف‌ها"},{"a":"salary","b":"pay / earnings","tr":"maaş","fa":"حقوق"},{"a":"recent","b":"latest / most up to date","tr":"en son","fa":"جدیدترین"}],"traps":[{"en":"Advice for different stages: \"before the interview\" and \"after the interview\" are different paragraphs.","tr":"Farklı aşamalar için tavsiyeler: \"mülakattan önce\" ve \"mülakattan sonra\" farklı paragraflardadır.","fa":"توصیه برای مرحله‌های مختلف: «قبل از مصاحبه» و «بعد از مصاحبه» در پاراگراف‌های جدا هستند."},{"en":"The gap needs a word from the text, even if a synonym feels more natural.","tr":"Boşluk metinden bir kelime ister; eş anlamlısı daha doğal gelse bile.","fa":"جای خالی کلمه‌ای از متن را می‌خواهد، حتی اگر مترادفش طبیعی‌تر به نظر برسد."}],"example":{"text":"Most employers spend less than a minute on each CV, so keep yours to two pages and put your most recent job first.","item":"Sentence: Put your most ___ job first.   (ONE WORD ONLY)","answer":"recent","why":{"en":"\"Put your most recent job first.\" Copy recent; do not change it to \"latest\".","tr":"\"En son işini en başa koy.\" recent kelimesini kopyala; \"latest\" diye değiştirme.","fa":"«جدیدترین شغلت را اول بنویس». کلمه‌ی recent را کپی کن؛ به latest تغییرش نده."}},"track":"gt","general":true,"patterns":["GT2-career"],"often":{"pattern":"GT2-career","n":18,"of":55,"label":{"en":"Comes up often in the real exam: 18 of the last 55 texts","tr":"Gerçek sınavda sık çıkar: son 55 metnin 18’inde","fa":"در آزمون واقعی زیاد می‌آید: در ۱۸ متن از ۵۵ متنِ اخیر"}}}]},"points":[{"eyebrow":{"en":"In the exam","tr":"Sınavda","fa":"در آزمون"},"head":{"en":"Notes, then sentences","tr":"Önce notlar, sonra cümleler","fa":"اول یادداشت، بعد جمله"},"body":{"en":"Questions 15-21: complete notes on the first text. Questions 22-27: complete sentences on the second text. Write ONE WORD ONLY from the text each time. The answers follow the order of each text.","tr":"Soru 15-21: birinci metinle ilgili notları tamamla. Soru 22-27: ikinci metinle ilgili cümleleri tamamla. Her seferinde metinden YALNIZCA BİR KELİME yaz. Cevaplar her metnin sırasını izler.","fa":"سؤال‌های ۱۵ تا ۲۱: یادداشت‌های متن اول را کامل کن. سؤال‌های ۲۲ تا ۲۷: جمله‌های متن دوم را کامل کن. هر بار فقط یک کلمه از متن بنویس. جواب‌ها به ترتیب هر متن می‌آیند."}},{"eyebrow":{"en":"The method","tr":"Yöntem","fa":"روش"},"head":{"en":"Four steps","tr":"Dört adım","fa":"چهار قدم"},"steps":[{"en":"Read the heading of each note; find the same stage in the text.","tr":"Her notun başlığını oku; metinde aynı aşamayı bul.","fa":"عنوان هر یادداشت را بخوان؛ همان مرحله را در متن پیدا کن."},{"en":"Predict the gap: a noun after \"a\" or \"the\", a past participle after \"was\", a plural after \"many\".","tr":"Boşluğu tahmin et: \"a\" ya da \"the\"den sonra isim, \"was\"tan sonra geçmiş ortaç, \"many\"den sonra çoğul.","fa":"جای خالی را حدس بزن: بعد از «a» یا «the» اسم، بعد از «was» صفت مفعولی، بعد از «many» جمع."},{"en":"Find the paraphrase in the text and copy the word exactly.","tr":"Metinde eş anlamlıyı bul ve kelimeyi aynen kopyala.","fa":"معادل را در متن پیدا کن و کلمه را دقیقاً کپی کن."},{"en":"Read the completed line again: it must be grammatical and true to the text.","tr":"Tamamlanan satırı tekrar oku: dilbilgisi doğru ve metne uygun olmalı.","fa":"خط کامل‌شده را دوباره بخوان: باید هم دستوری درست باشد و هم با متن جور."}]},{"eyebrow":{"en":"The trap","tr":"Tuzak","fa":"دام"},"head":{"en":"Right meaning, wrong word","tr":"Doğru anlam, yanlış kelime","fa":"معنی درست، کلمه‌ی غلط"},"body":{"en":"A synonym is wrong even if it means the same: if the text says \"fee\", \"payment\" scores nothing. Check the form too: \"generalists\", not \"generalist\", if the text uses the plural.","tr":"Eş anlamlı bir kelime aynı anlama gelse bile yanlıştır: metin \"fee\" diyorsa \"payment\" puan almaz. Biçimi de kontrol et: metin çoğul kullanıyorsa \"generalist\" değil \"generalists\".","fa":"مترادف حتی اگر هم‌معنی باشد غلط است: اگر متن می‌گوید «fee»، «payment» نمره ندارد. شکل کلمه را هم چک کن: اگر متن جمع آورده، «generalists» نه «generalist»."}}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"One note, step by step","tr":"Bir not, adım adım","fa":"یک یادداشت، قدم به قدم"},"instruction":"Complete the notes below. Choose ONE WORD ONLY from the text for each answer.","text":"\"Most new drivers are offered a contract for six months; if their work is satisfactory, this becomes permanent.\"","item":"Contract · becomes ___ if work is good","answer":"permanent","walk":[{"en":"The heading is Contract; the gap follows \"becomes\", so it needs an adjective.","tr":"Başlık Contract; boşluk \"becomes\"ten sonra geliyor, yani bir sıfat gerekiyor.","fa":"عنوان Contract است؛ جای خالی بعد از «becomes» است، پس صفت می‌خواهد."},{"en":"\"If work is good\" = \"if their work is satisfactory\".","tr":"\"If work is good\" = \"if their work is satisfactory\".","fa":"«if work is good» یعنی «if their work is satisfactory»."},{"en":"Copy the adjective: permanent.","tr":"Sıfatı kopyala: permanent.","fa":"صفت را کپی کن: permanent."}]},"quick":{"prompt":"Text: \"Uniforms are provided, but staff must buy their own safety boots.\" Note: \"Staff pay for their own ___ (ONE WORD ONLY)\". What do you write?","options":["uniforms","boots","safety boots"],"correct":1,"why":{"en":"Uniforms are provided; boots are what staff buy. \"Safety boots\" is two words.","tr":"Üniformalar veriliyor; botları personel alıyor. \"Safety boots\" iki kelime.","fa":"یونیفرم داده می‌شود؛ پوتین را خود کارکنان می‌خرند. «safety boots» دو کلمه است."}},"remember":{"en":"Find the meaning, copy the exact word, keep its form.","tr":"Anlamı bul, kelimeyi aynen kopyala, biçimini koru.","fa":"معنی را پیدا کن، کلمه را دقیق کپی کن، شکلش را نگه دار."},"type":"explain","id":"c-x08-r2-e-gt","course":"ielts-exams","exam":"exam-08","unit":"x08-r2"},"drill":{"type":"drill","skill":"reading","part":"General Training Reading Section 2","title":{"en":"Translation work and cover letters","tr":"Çeviri işi ve ön yazılar","fa":"کار ترجمه و نامه‌ی همراه رزومه"},"timed":20,"ctx":["GT2-career"],"texts":[{"title":"Working as a freelance translator","kind":"career article","body":"Many people who speak two or more languages well imagine that translation would be an easy way to work from home. In reality, it is a demanding profession, and those who succeed treat it as a business from the first day.\n\nMost freelance translators begin with a degree in languages, but a qualification in translation itself is increasingly expected by agencies. It is also wise to choose a specialism early. Translators who know a field such as law, medicine or engineering can charge more than generalists, because clients need someone who understands the subject as well as the language. A mistake in a contract or a set of instructions can be very costly.\n\nFinding the first clients is usually the hardest stage. Agencies are the most common starting point, as they pass on a steady flow of work, although they keep part of the fee. Some translators also contact companies directly, but this requires confidence and a good portfolio of past work. Joining a professional association helps, since members are listed in a directory that clients consult.\n\nIncome varies widely. Translators are normally paid per word, and rates depend on the language pair: less common languages often earn more, because there are fewer people who can do the work. In the first year, many freelancers earn very little, so experienced translators advise saving enough to live on for at least six months before giving up a salaried job.\n\nWorking alone has drawbacks. Deadlines can be very tight, and translators may receive a large project on a Friday afternoon that must be finished by Monday. It is also easy to feel isolated. Many freelancers deal with this by sharing an office with other self-employed people or by taking part in online forums where they can ask colleagues about difficult terms.\n\nFinally, technology is changing the job. Machine translation now produces a rough version of many texts in seconds, and some clients pay translators simply to correct it, at a lower rate. Rather than seeing this as a threat, successful translators focus on work that machines still do badly, such as marketing material, where the tone matters as much as the meaning."},{"title":"How to write a cover letter that gets read","kind":"guide","body":"A cover letter is the first thing many employers read, and it often decides whether your application goes any further. These guidelines will help you make a good impression.\n\nKeep it short\nRecruiters may read hundreds of applications for one post. A letter that fits on a single page is far more likely to be read in full than one that runs to two or three.\n\nAddress a real person\nWherever possible, find out the name of the person who will read your letter. A quick call to the company or a look at its website is usually enough. Letters addressed to \"Sir or Madam\" can suggest that you have sent the same text to many employers.\n\nOpen with the job\nIn your first sentence, say which position you are applying for and where you saw it advertised. Employers often have several vacancies at the same time.\n\nMatch yourself to the advert\nRead the job description carefully and choose two or three of the main requirements. For each one, give a short example from your experience that shows you have that skill. Avoid simply repeating what is in your CV; the letter should explain how your experience fits this particular role.\n\nShow some knowledge of the company\nMention something specific about the organisation, such as a recent project or its values. This shows that you are genuinely interested and have done some research.\n\nEnd positively\nClose by saying that you would welcome the chance to discuss your application at an interview, and thank the reader for their time. Do not end by asking about salary or holidays.\n\nCheck every word\nSpelling mistakes suggest carelessness, so read your letter aloud before you send it, or ask a friend to check it. Make sure that the company's name is spelled correctly, as this is a common error."}],"groups":[{"text":0,"instruction":"Questions 15-21. Complete the notes below. Choose ONE WORD ONLY from the text for each answer.","qtype":"note","notesTitle":"Freelance translation","questions":[{"n":15,"kind":"gap","prompt":"Getting started · agencies now often want a qualification in ___","accept":["translation"],"limit":1,"evidence":"a qualification in translation itself is increasingly expected by agencies","why":{"en":"\"Increasingly expected by agencies\" = agencies now often want it.","tr":"\"Ajanslar giderek daha çok bekliyor\" = ajanslar artık sıkça istiyor.","fa":"«آژانس‌ها روزبه‌روز بیشتر انتظارش را دارند» یعنی حالا اغلب می‌خواهندش."},"trap":["TR-paraphrase"]},{"n":16,"kind":"gap","prompt":"Getting started · specialists can charge more than ___","accept":["generalists"],"limit":1,"evidence":"can charge more than generalists","why":{"en":"Specialists in law, medicine or engineering \"can charge more than generalists\". Plural.","tr":"Hukuk, tıp ya da mühendislik uzmanları \"genel çevirmenlerden daha fazla ücret alabilir\". Çoğul.","fa":"متخصص‌های حقوق، پزشکی یا مهندسی «می‌توانند از مترجم‌های عمومی بیشتر پول بگیرند». جمع."},"trap":["TR-plural"]},{"n":17,"kind":"gap","prompt":"Finding clients · agencies keep part of the ___","accept":["fee"],"limit":1,"evidence":"although they keep part of the fee","why":{"en":"Agencies give steady work \"although they keep part of the fee\".","tr":"Ajanslar düzenli iş verir \"ama ücretin bir kısmını alırlar\".","fa":"آژانس‌ها کار منظم می‌دهند، «هرچند بخشی از دستمزد را برمی‌دارند»."},"trap":["TR-paraphrase"]},{"n":18,"kind":"gap","prompt":"Finding clients · association members appear in a ___ used by clients","accept":["directory"],"limit":1,"evidence":"members are listed in a directory that clients consult","why":{"en":"\"Listed in a directory that clients consult\".","tr":"\"Müşterilerin baktığı bir rehberde listelenirler\".","fa":"«در فهرستی ثبت می‌شوند که مشتری‌ها به آن مراجعه می‌کنند»."},"trap":["TR-paraphrase"]},{"n":19,"kind":"gap","prompt":"Income · payment is usually calculated per ___","accept":["word"],"limit":1,"evidence":"Translators are normally paid per word","why":{"en":"\"Normally paid per word\" = usually calculated per word.","tr":"\"Genellikle kelime başına ödenir\".","fa":"«معمولاً به ازای هر کلمه پول می‌گیرند»."},"trap":["TR-paraphrase"]},{"n":20,"kind":"gap","prompt":"Income · before leaving a job, save enough to live on for six ___","accept":["months"],"limit":1,"evidence":"for at least six months","why":{"en":"\"At least six months\". \"six\" is printed; write months.","tr":"\"En az altı ay\". \"six\" yazılı; months yaz.","fa":"«دست‌کم شش ماه». «six» چاپ شده؛ months را بنویس."},"trap":["TR-plural","TR-limit"]},{"n":21,"kind":"gap","prompt":"Problems · to feel less isolated, some share an ___ with other freelancers","accept":["office"],"limit":1,"evidence":"sharing an office with other self-employed people","why":{"en":"\"Sharing an office with other self-employed people\": self-employed = freelancers.","tr":"\"Diğer serbest çalışanlarla bir ofisi paylaşmak\": self-employed = freelancers.","fa":"«یک دفتر را با آدم‌های خویش‌فرمای دیگر شریک شدن»: self-employed یعنی freelancers."},"trap":["TR-paraphrase"]}]},{"text":1,"instruction":"Questions 22-27. Complete the sentences below. Choose ONE WORD ONLY from the text for each answer.","qtype":"sentence","questions":[{"n":22,"kind":"gap","prompt":"A letter that is just one ___ long is more likely to be read completely.","accept":["page"],"limit":1,"evidence":"A letter that fits on a single page","why":{"en":"\"Fits on a single page\" = one page long.","tr":"\"Tek bir sayfaya sığan\" = bir sayfa uzunluğunda.","fa":"«روی یک صفحه جا می‌شود» یعنی یک صفحه."},"trap":["TR-paraphrase"]},{"n":23,"kind":"gap","prompt":"A letter starting \"Dear Sir or Madam\" may suggest you wrote to many ___ with the same text.","accept":["employers"],"limit":1,"evidence":"sent the same text to many employers","why":{"en":"\"Sent the same text to many employers\". Plural.","tr":"\"Aynı metni birçok işverene göndermek\". Çoğul.","fa":"«یک متن را برای کارفرماهای زیادی فرستادن». جمع."},"trap":["TR-plural"]},{"n":24,"kind":"gap","prompt":"The first sentence should name the job and say where it was ___.","accept":["advertised"],"limit":1,"evidence":"where you saw it advertised","why":{"en":"\"Where you saw it advertised\" = where it was advertised.","tr":"\"Nerede ilan edildiğini gördüğün\" = nerede ilan edildiği.","fa":"«کجا آگهی‌اش را دیدی» یعنی کجا آگهی شده بود."},"trap":["TR-paraphrase"]},{"n":25,"kind":"gap","prompt":"For each main requirement, give an ___ from your own experience.","accept":["example"],"limit":1,"evidence":"give a short example from your experience","why":{"en":"\"Give a short example from your experience\".","tr":"\"Deneyiminden kısa bir örnek ver\".","fa":"«یک مثال کوتاه از تجربه‌ات بیاور»."},"trap":["TR-paraphrase"]},{"n":26,"kind":"gap","prompt":"Mentioning something specific about the company shows you have done some ___.","accept":["research"],"limit":1,"evidence":"have done some research","why":{"en":"\"Shows that you are genuinely interested and have done some research\".","tr":"\"Gerçekten ilgilendiğini ve biraz araştırma yaptığını gösterir\".","fa":"«نشان می‌دهد واقعاً علاقه داری و کمی تحقیق کرده‌ای»."},"trap":["TR-paraphrase"]},{"n":27,"kind":"gap","prompt":"Reading the letter ___ can help you find spelling mistakes.","accept":["aloud"],"limit":1,"evidence":"read your letter aloud before you send it","why":{"en":"\"Read your letter aloud before you send it\".","tr":"\"Göndermeden önce mektubunu yüksek sesle oku\".","fa":"«قبل از فرستادن، نامه‌ات را بلند بخوان»."},"trap":["TR-paraphrase"]}]}],"id":"c-x08-r2-d-gt","course":"ielts-exams","exam":"exam-08","unit":"x08-r2"},"exit":{"type":"exit","items":[{"tests":"word","point":1,"prompt":"A guide mentions \"recruiters\". Recruiters are...","options":["people who find and choose new staff","people who have just started a job","people who train new staff"],"correct":0,"why":{"en":"Recruiters look for and select people for jobs.","tr":"Recruiter, işler için insan arayan ve seçen kişidir.","fa":"recruiter کسی است که برای کارها آدم پیدا و انتخاب می‌کند."}},{"tests":"paraphrase","point":1,"prompt":"A note says \"lonely\". Which word in an article could you look for?","options":["independent","experienced","isolated"],"correct":2,"why":{"en":"Isolated = alone, cut off from other people.","tr":"Isolated = yalnız, başkalarından kopuk.","fa":"isolated یعنی تنها، جدا از دیگران."}},{"tests":"method","point":2,"prompt":"Sentence: \"Applicants should give an ___ from their experience.\" What kind of word fits?","options":["a verb","a noun starting with a vowel sound","a plural noun"],"correct":1,"why":{"en":"\"An\" comes before a singular noun that starts with a vowel sound (example, idea).","tr":"\"An\", ünlü sesle başlayan tekil bir isimden önce gelir (example, idea).","fa":"«an» قبل از اسم مفردی می‌آید که با صدای مصوت شروع می‌شود (example، idea)."}},{"tests":"trap","point":3,"prompt":"Text: \"Contact the manager by phone.\" Sentence: \"Applicants should ___ the manager.\" (ONE WORD ONLY) Which answer is acceptable?","options":["contact","call","phone the"],"correct":0,"why":{"en":"Only the word in the text is accepted: contact. \"Call\" means the same but is not in the text.","tr":"Yalnızca metindeki kelime kabul edilir: contact. \"Call\" aynı anlama gelir ama metinde yok.","fa":"فقط کلمه‌ی متن قبول است: contact. «call» هم‌معنی است، اما در متن نیست."}}],"id":"c-x08-r2-x-gt","course":"ielts-exams","exam":"exam-08","unit":"x08-r2"}}}; })(globalThis.IELTS_EXAMS = globalThis.IELTS_EXAMS || {});
